def rep(old, new, count=1):
    global s
    n = s.count(old)
    if n < 1:
        sys.exit('NOT FOUND: ' + old[:80])
    if count == 1 and n != 1:
        sys.exit('NOT UNIQUE (%d): %s' % (n, old[:80]))
    s = s.replace(old, new)

